() => {
  // Get the main container
  const container = document.querySelector('body > div');
  if (!container) return { success: false, message: 'No container found' };

  // Simulate touch events
  const touchStart = new TouchEvent('touchstart', {
    bubbles: true,
    cancelable: true,
    view: window,
    touches: [new Touch({
      identifier: 0,
      target: container,
      clientX: window.innerWidth / 2,
      clientY: window.innerHeight / 2
    })]
  });

  container.dispatchEvent(touchStart);
  return { success: true, dispatched: 'touchstart' };
}

() => {
  const container = document.querySelector('body > div');
  if (!container) return { success: false, message: 'No container found' };

  const touchEnd = new TouchEvent('touchend', {
    bubbles: true,
    cancelable: true,
    view: window,
    changedTouches: [new Touch({
      identifier: 0,
      target: container,
      clientX: window.innerWidth / 2,
      clientY: window.innerHeight / 2
    })]
  });

  container.dispatchEvent(touchEnd);
  return { success: true, dispatched: 'touchend' };
}

() => {
  const container = document.querySelector('body > div');
  if (!container) return { success: false, message: 'No container found' };

  // Get the center of the element
  const rect = container.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  // Simulate mousedown
  const mouseDown = new MouseEvent('mousedown', {
    bubbles: true,
    cancelable: true,
    view: window,
    clientX: x,
    clientY: y,
    button: 0
  });

  container.dispatchEvent(mouseDown);
  return { success: true, dispatched: 'mousedown', x, y };
}

